# Task: Implement editLLM section editor

## Objective
Implement the LLM configuration section editor with all 8 fields.

## Implementation Details

### Add to: src/lib/config-tui.ts

```typescript
/**
 * Edit LLM configuration section
 */
async function editLLM(
  state: TUIState,
  currentConfig: MgrepConfig
): Promise<void> {
  const current = currentConfig.llm;
  const editing = (state.config.llm || {}) as Partial<typeof current>;

  while (true) {
    const field = await p.select({
      message: "LLM - Select field to edit:",
      options: [
        {
          value: "provider",
          label: `Provider: ${editing.provider || current.provider}`,
          hint: "openai, google, anthropic, ollama",
        },
        {
          value: "model",
          label: `Model: ${editing.model || current.model}`,
          hint: "e.g., gpt-4o-mini, claude-sonnet-4, llama3.2",
        },
        {
          value: "baseUrl",
          label: `Base URL: ${getDisplayValue(editing.baseUrl ?? current.baseUrl)}`,
          hint: "Custom API endpoint",
        },
        {
          value: "apiKey",
          label: `API Key: ${getDisplayValue(editing.apiKey ?? current.apiKey, true)}`,
          hint: "API key (stored in config)",
        },
        {
          value: "temperature",
          label: `Temperature: ${editing.temperature ?? current.temperature}`,
          hint: "0-2, controls randomness (default: 0.7)",
        },
        {
          value: "maxTokens",
          label: `Max Tokens: ${editing.maxTokens || current.maxTokens}`,
          hint: "Maximum output tokens (default: 4096)",
        },
        {
          value: "timeoutMs",
          label: `Timeout: ${editing.timeoutMs || current.timeoutMs}ms`,
          hint: "Request timeout in milliseconds",
        },
        {
          value: "maxRetries",
          label: `Max Retries: ${editing.maxRetries ?? current.maxRetries}`,
          hint: "Number of retry attempts (default: 3)",
        },
        { value: "back", label: "<- Back", hint: "Return to main menu" },
      ],
    });

    if (p.isCancel(field) || field === "back") return;

    let newValue: unknown;

    switch (field) {
      case "provider":
        newValue = await editField("provider", "provider", editing.provider || current.provider);
        break;
      case "model":
        newValue = await editField("text", "model", editing.model || current.model, {
          placeholder: "e.g., gpt-4o-mini",
        });
        break;
      case "baseUrl":
        newValue = await editField("text", "base URL", editing.baseUrl ?? current.baseUrl, {
          placeholder: "https://api.example.com/v1",
        });
        break;
      case "apiKey":
        newValue = await editField("password", "API key", undefined);
        break;
      case "temperature":
        newValue = await editField("temperature", "temperature", editing.temperature ?? current.temperature);
        break;
      case "maxTokens":
        newValue = await editField("positiveNumber", "max tokens", editing.maxTokens || current.maxTokens, {
          max: 128000,
        });
        break;
      case "timeoutMs":
        newValue = await editField("positiveNumber", "timeout (ms)", editing.timeoutMs || current.timeoutMs, {
          max: 600000,
        });
        break;
      case "maxRetries":
        newValue = await editField("number", "max retries", editing.maxRetries ?? current.maxRetries, {
          min: 0,
          max: 10,
        });
        break;
    }

    if (newValue !== undefined) {
      if (!state.config.llm) {
        state.config.llm = {};
      }
      (state.config.llm as Record<string, unknown>)[field] = newValue;
      state.hasChanges = true;
    }
  }
}
```

## Fields

| Field | Type | Validation | Default |
|-------|------|------------|---------|
| provider | select | openai/google/anthropic/ollama | openai |
| model | text | none | gpt-4o-mini |
| baseUrl | text | none (optional) | - |
| apiKey | password | masked | - |
| temperature | temperature | 0-2 | 0.7 |
| maxTokens | positiveNumber | 1-128000 | 4096 |
| timeoutMs | positiveNumber | 1-600000 | 60000 |
| maxRetries | number | 0-10 | 3 |

