Implement native selector using @clack/prompts:

## Implementation
Add to src/lib/fzf-pipe.ts or src/commands/search.ts:

```typescript
import * as p from '@clack/prompts';

const MAX_NATIVE_SELECT_RESULTS = 20;

async function nativeSelect(results: SearchResultForFzf[]): Promise<FzfResult | null> {
  // Warn user
  console.error(chalk.yellow('fzf not found. Using built-in selector.'));
  console.error(chalk.gray('Tip: Install fzf for better experience: https://github.com/junegunn/fzf'));

  if (results.length === 0) return null;

  // Limit results
  const limitedResults = results.slice(0, MAX_NATIVE_SELECT_RESULTS);
  if (results.length > MAX_NATIVE_SELECT_RESULTS) {
    console.error(chalk.gray(`Showing top ${MAX_NATIVE_SELECT_RESULTS} of ${results.length} results.`));
  }

  // Build options
  const options = limitedResults.map((r, i) => ({
    value: i,
    label: `${r.path.replace(process.cwd(), '.')}:${r.startLine}`,
    hint: `${(r.score * 100).toFixed(0)}% - ${r.preview.slice(0, 50)}...`
  }));

  const selected = await p.select({ message: 'Select a result:', options });

  if (p.isCancel(selected)) return null;

  const result = limitedResults[selected as number];
  return { selected: true, filePath: result.path, lineNumber: result.startLine };
}
```

## Acceptance Criteria
- [ ] Warning message shown
- [ ] fzf installation link shown
- [ ] Results limited to 20
- [ ] Truncation message shown when > 20 results
- [ ] Cancellation handled

