# Task: Create config-tui.ts with TUIState and core structure

## Objective
Create the main TUI module src/lib/config-tui.ts with the core types, state management, and entry point function.

## Implementation Details

### File: src/lib/config-tui.ts

```typescript
import * as p from "@clack/prompts";
import chalk from "chalk";
import YAML from "yaml";
import {
  type MgrepConfig,
  DEFAULT_CONFIG,
  loadConfig,
  type ProviderType,
} from "./config.js";
import {
  type ConfigTarget,
  writeConfig,
  readExistingConfig,
  getConfigFilePath,
} from "./config-writer.js";

/**
 * Available configuration sections
 */
type ConfigSection =
  | "embeddings"
  | "llm"
  | "qdrant"
  | "sync"
  | "tavily"
  | "ignore"
  | "general";

/**
 * TUI state management
 */
interface TUIState {
  /** Target config file (global or local) */
  target: ConfigTarget;
  /** Pending configuration changes */
  config: Partial<MgrepConfig>;
  /** Whether there are unsaved changes */
  hasChanges: boolean;
  /** Current working directory */
  cwd: string;
}

/**
 * Options for running the config TUI
 */
export interface ConfigTUIOptions {
  /** Edit global config directly */
  global?: boolean;
  /** Edit local config directly */
  local?: boolean;
}

/**
 * Main entry point for the config TUI
 * @param options - CLI options for target selection
 */
export async function runConfigTUI(options: ConfigTUIOptions): Promise<void> {
  p.intro(chalk.cyan("mgrep configuration"));

  // Determine target
  const target = await selectConfigTarget(options);
  if (!target) return;

  const cwd = process.cwd();
  const existingConfig = readExistingConfig(target, cwd);
  const mergedConfig = loadConfig(cwd);

  const state: TUIState = {
    target,
    config: existingConfig || {},
    hasChanges: false,
    cwd,
  };

  // Show config file info
  const configPath = getConfigFilePath(target, cwd);
  p.note(
    existingConfig
      ? `Editing: ${configPath}`
      : `Creating new: ${configPath}`,
    target === "global" ? "Global Config" : "Local Config"
  );

  // Run main menu loop
  await mainMenuLoop(state, mergedConfig);
}

/**
 * Select configuration target (global or local)
 */
async function selectConfigTarget(
  options: ConfigTUIOptions
): Promise<ConfigTarget | null> {
  if (options.global) return "global";
  if (options.local) return "local";

  const target = await p.select({
    message: "Which configuration do you want to edit?",
    options: [
      {
        value: "global",
        label: "Global",
        hint: "~/.config/mgrep/config.yaml - applies to all projects",
      },
      {
        value: "local",
        label: "Local",
        hint: ".mgreprc.yaml - applies to current project only",
      },
    ],
  });

  if (p.isCancel(target)) {
    p.cancel("Configuration cancelled.");
    return null;
  }

  return target as ConfigTarget;
}

// Placeholder functions to be implemented in subsequent tasks
async function mainMenuLoop(state: TUIState, currentConfig: MgrepConfig): Promise<void> {
  // Will be implemented in Phase 2.2
  p.log.info("Main menu not yet implemented");
}
```

## Types and Interfaces

### TUIState
- `target`: ConfigTarget - Whether editing global or local config
- `config`: Partial<MgrepConfig> - The pending changes to be saved
- `hasChanges`: boolean - Track if user made any changes
- `cwd`: string - Current working directory for local config path

### ConfigTUIOptions
- `global?: boolean` - Skip selection, edit global directly
- `local?: boolean` - Skip selection, edit local directly

## Acceptance Criteria
- [ ] File compiles without TypeScript errors
- [ ] runConfigTUI function is exported and callable
- [ ] selectConfigTarget respects --global and --local flags
- [ ] selectConfigTarget prompts user when no flag provided
- [ ] Intro message displays correctly
- [ ] Config file path is displayed in note
- [ ] Cancel handling works (Ctrl+C exits gracefully)

## Technical Notes
- Use @clack/prompts consistently for all UI
- Match visual style of existing mgrep init command
- State is passed by reference to allow mutations in editor functions

