```typescript
/**
 * Edit Sync configuration section
 */
async function editSync(
  state: TUIState,
  currentConfig: MgrepConfig
): Promise<void> {
  const current = currentConfig.sync;
  const editing = (state.config.sync || {}) as Partial<typeof current>;

  const value = await p.text({
    message: "Enter sync concurrency (parallel file operations):",
    initialValue: (editing.concurrency || current.concurrency).toString(),
    validate: (v) => {
      const num = Number.parseInt(v, 10);
      if (Number.isNaN(num) || num < 1 || num > 100) {
        return "Concurrency must be between 1 and 100";
      }
      return undefined;
    },
  });

  if (!p.isCancel(value)) {
    state.config.sync = { concurrency: Number.parseInt(value, 10) };
    state.hasChanges = true;
  }
}
```

