# Task: Create config-writer.ts module

## Objective
Create a new module src/lib/config-writer.ts that handles reading and writing configuration files to both global and local paths.

## Implementation Details

### File: src/lib/config-writer.ts

```typescript
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import YAML from "yaml";
import type { MgrepConfig } from "./config.js";

/**
 * Target for configuration file - global or local
 */
export type ConfigTarget = "global" | "local";

/**
 * Get the file path for the specified config target
 * @param target - "global" for ~/.config/mgrep/config.yaml, "local" for .mgreprc.yaml
 * @param cwd - Current working directory (used for local config)
 */
export function getConfigFilePath(target: ConfigTarget, cwd: string): string {
  if (target === "global") {
    return path.join(os.homedir(), ".config", "mgrep", "config.yaml");
  }
  return path.join(cwd, ".mgreprc.yaml");
}

/**
 * Write configuration to file
 * Creates directory if it doesn't exist
 * @param config - Partial config object to write
 * @param target - Where to write (global or local)
 * @param cwd - Current working directory
 */
export function writeConfig(
  config: Partial<MgrepConfig>,
  target: ConfigTarget,
  cwd: string
): void {
  const filePath = getConfigFilePath(target, cwd);
  const dir = path.dirname(filePath);

  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  const header = target === "global"
    ? "# mgrep global configuration\n# Edit with: mgrep config --global\n\n"
    : "# mgrep project configuration\n# Edit with: mgrep config --local\n\n";

  const yamlContent = YAML.stringify(config);
  fs.writeFileSync(filePath, `${header}${yamlContent}`, "utf-8");
}

/**
 * Read existing configuration from file
 * @param target - Where to read from (global or local)
 * @param cwd - Current working directory
 * @returns Partial config or null if file doesn't exist
 */
export function readExistingConfig(
  target: ConfigTarget,
  cwd: string
): Partial<MgrepConfig> | null {
  const filePath = getConfigFilePath(target, cwd);

  if (!fs.existsSync(filePath)) {
    return null;
  }

  try {
    const content = fs.readFileSync(filePath, "utf-8");
    return YAML.parse(content) as Partial<MgrepConfig>;
  } catch {
    return null;
  }
}

/**
 * Check if a config file exists at the specified target
 */
export function configExists(target: ConfigTarget, cwd: string): boolean {
  const filePath = getConfigFilePath(target, cwd);
  return fs.existsSync(filePath);
}
```

## Acceptance Criteria
- [ ] getConfigFilePath returns correct paths for global and local targets
- [ ] writeConfig creates directory if it doesn't exist
- [ ] writeConfig writes valid YAML with appropriate header
- [ ] readExistingConfig returns null for non-existent files
- [ ] readExistingConfig parses valid YAML correctly
- [ ] readExistingConfig handles parse errors gracefully (returns null)
- [ ] configExists returns correct boolean values
- [ ] TypeScript types are properly exported

## Edge Cases to Handle
- Directory doesn't exist (create it)
- Invalid YAML in existing file (return null, don't crash)
- Permission errors (let them propagate for caller to handle)

