## Objective
Implement cross-platform clipboard support for the context command.

## Implementation Steps

### 1. Create clipboard utility
Create `src/lib/clipboard.ts`:

```typescript
import { exec } from "node:child_process";
import { promisify } from "node:util";

const execAsync = promisify(exec);

interface ClipboardResult {
  success: boolean;
  error?: string;
}

export async function copyToClipboard(text: string): Promise<ClipboardResult> {
  const platform = process.platform;

  try {
    if (platform === "darwin") {
      // macOS: use pbcopy
      await execAsync("pbcopy", { input: text });
    } else if (platform === "win32") {
      // Windows: use clip.exe
      await execAsync("clip", { input: text });
    } else {
      // Linux: try xclip, then xsel, then wl-copy (Wayland)
      try {
        await execAsync("xclip -selection clipboard", { input: text });
      } catch {
        try {
          await execAsync("xsel --clipboard --input", { input: text });
        } catch {
          await execAsync("wl-copy", { input: text });
        }
      }
    }
    return { success: true };
  } catch (error) {
    return { 
      success: false, 
      error: `Clipboard not available: ${error.message}` 
    };
  }
}

export function isClipboardAvailable(): boolean {
