/**
 * Main menu loop - handles section navigation
 */
async function mainMenuLoop(
  state: TUIState,
  currentConfig: MgrepConfig
): Promise<void> {
  while (true) {
    const saveLabel = state.hasChanges ? "Save & Exit" : "Exit";
    const saveHint = state.hasChanges
      ? "Save changes and exit"
      : "Exit without changes";

    const action = await p.select({
      message: "What would you like to configure?",
      options: [
        {
          value: "embeddings",
          label: "Embeddings",
          hint: "AI embedding provider settings",
        },
        {
          value: "llm",
          label: "LLM",
          hint: "Language model settings",
        },
        {
          value: "qdrant",
          label: "Qdrant",
          hint: "Vector database settings",
        },
        {
          value: "sync",
          label: "Sync",
          hint: "File synchronization settings",
        },
        {
          value: "tavily",
          label: "Tavily",
          hint: "Web search settings",
        },
        {
          value: "ignore",
          label: "Ignore",
          hint: "File ignore patterns",
        },
        {
          value: "general",
          label: "General",
          hint: "Max file size and other settings",
        },
        {
          value: "view",
          label: "View Current Config",
          hint: "Show full configuration",
        },
        {
          value: "save",
          label: saveLabel,
          hint: saveHint,
        },
      ],
    });

    // Handle cancel (Ctrl+C)
    if (p.isCancel(action)) {
      if (state.hasChanges) {
        const confirm = await p.confirm({
          message: "You have unsaved changes. Exit anyway?",
          initialValue: false,
        });
        if (p.isCancel(confirm) || !confirm) continue;
      }
      p.cancel("Configuration cancelled.");
      return;
    }

    // Route to appropriate handler
    switch (action) {
      case "embeddings":
        await editEmbeddings(state, currentConfig);
        break;
      case "llm":
        await editLLM(state, currentConfig);
        break;
      case "qdrant":
        await editQdrant(state, currentConfig);
        break;
      case "sync":
        await editSync(state, currentConfig);
        break;
      case "tavily":
        await editTavily(state, currentConfig);
        break;
      case "ignore":
        await editIgnore(state, currentConfig);
        break;
      case "general":
        await editGeneral(state, currentConfig);
        break;
      case "view":
        viewCurrentConfig(state, currentConfig);
        break;
      case "save":
        if (state.hasChanges) {
          await saveConfig(state);
        }
        p.outro(chalk.green("Configuration complete!"));
        return;
    }
  }
}

