/**
 * Edit Embeddings configuration section
 */
async function editEmbeddings(
  state: TUIState,
  currentConfig: MgrepConfig
): Promise<void> {
  const current = currentConfig.embeddings;
  const editing = (state.config.embeddings || {}) as Partial<typeof current>;

  while (true) {
    const field = await p.select({
      message: "Embeddings - Select field to edit:",
      options: [
        {
          value: "provider",
          label: `Provider: ${editing.provider || current.provider}`,
          hint: "openai, google, anthropic, ollama",
        },
        {
          value: "model",
          label: `Model: ${editing.model || current.model}`,
          hint: "e.g., text-embedding-3-small, nomic-embed-text",
        },
        {
          value: "baseUrl",
          label: `Base URL: ${getDisplayValue(editing.baseUrl ?? current.baseUrl)}`,
          hint: "Custom API endpoint (for Ollama, vLLM)",
        },
        {
          value: "apiKey",
          label: `API Key: ${getDisplayValue(editing.apiKey ?? current.apiKey, true)}`,
          hint: "API key (stored in config)",
        },
        {
          value: "dimensions",
          label: `Dimensions: ${getDisplayValue(editing.dimensions ?? current.dimensions)}`,
          hint: "Vector dimensions (768, 1024, 1536, etc.)",
        },
        {
          value: "batchSize",
          label: `Batch Size: ${editing.batchSize || current.batchSize}`,
          hint: "Embeddings per batch (default: 100)",
        },
        {
          value: "timeoutMs",
          label: `Timeout: ${editing.timeoutMs || current.timeoutMs}ms`,
          hint: "Request timeout in milliseconds",
        },
        {
          value: "maxRetries",
          label: `Max Retries: ${editing.maxRetries ?? current.maxRetries}`,
          hint: "Number of retry attempts (default: 3)",
        },
        { value: "back", label: "<- Back", hint: "Return to main menu" },
      ],
    });

    if (p.isCancel(field) || field === "back") return;

    let newValue: unknown;

    switch (field) {
      case "provider":
        newValue = await editField("provider", "provider", editing.provider || current.provider);
        break;
      case "model":
        newValue = await editField("text", "model", editing.model || current.model, {
          placeholder: "e.g., text-embedding-3-small",
        });
        break;
      case "baseUrl":
        newValue = await editField("text", "base URL", editing.baseUrl ?? current.baseUrl, {
          placeholder: "https://api.example.com/v1",
        });
        break;
      case "apiKey":
        newValue = await editField("password", "API key", undefined);
        break;
      case "dimensions":
        newValue = await editField("positiveNumber", "dimensions", editing.dimensions ?? current.dimensions, {
          max: 4096,
        });
        break;
      case "batchSize":
        newValue = await editField("positiveNumber", "batch size", editing.batchSize || current.batchSize, {
          max: 1000,
        });
        break;
      case "timeoutMs":
        newValue = await editField("positiveNumber", "timeout (ms)", editing.timeoutMs || current.timeoutMs, {
          max: 300000,
        });
        break;
      case "maxRetries":
        newValue = await editField("number", "max retries", editing.maxRetries ?? current.maxRetries, {
          min: 0,
          max: 10,
        });
        break;
    }

    if (newValue !== undefined) {
      if (!state.config.embeddings) {
        state.config.embeddings = {};
      }
      (state.config.embeddings as Record<string, unknown>)[field] = newValue;
      state.hasChanges = true;
    }
  }
}
