/**
 * Edit General configuration section
 */
async function editGeneral(
  state: TUIState,
  currentConfig: MgrepConfig
): Promise<void> {
  const current = currentConfig.maxFileSize;
  const editing = state.config.maxFileSize;

  // Convert bytes to MB for user-friendly display
  const currentMB = (editing || current) / (1024 * 1024);

  const value = await p.text({
    message: "Enter max file size in MB (files larger than this will be skipped during sync):",
    initialValue: currentMB.toFixed(2),
    validate: (v) => {
      const num = Number.parseFloat(v);
      if (Number.isNaN(num) || num <= 0) {
        return "Please enter a valid positive number";
      }
      if (num > 100) {
        return "Max file size cannot exceed 100 MB";
      }
      if (num < 0.001) {
        return "Min file size is 0.001 MB (1 KB)";
      }
      return undefined;
    },
  });

  if (!p.isCancel(value)) {
    // Convert MB back to bytes
    const bytes = Math.round(Number.parseFloat(value) * 1024 * 1024);
    state.config.maxFileSize = bytes;
    state.hasChanges = true;

    // Show confirmation with formatted size
    const formattedSize = formatFileSize(bytes);
    p.log.success(`Max file size set to ${formattedSize}`);
  }
}

/**
 * Format bytes to human-readable string
 * (This may already exist in config.ts - reuse if so)
 */
function formatFileSizeLocal(bytes: number): string {
  const units = ["B", "KB", "MB", "GB"];
  let size = bytes;
  let unitIndex = 0;

  while (size >= 1024 && unitIndex < units.length - 1) {
    size /= 1024;
    unitIndex++;
  }

  return `${size.toFixed(unitIndex === 0 ? 0 : 2)} ${units[unitIndex]}`;
}
```

## UX Notes

1. **User Input in MB**: Users enter size in megabytes (more intuitive than bytes)
2. **Validation Range**: 0.001 MB (1 KB) to 100 MB
3. **Conversion**: Automatically converts between MB (display) and bytes (storage)
4. **Confirmation**: Shows formatted size after setting (e.g., "10.00 MB")

