/**
 * Edit Ignore configuration section
 */
async function editIgnore(
  state: TUIState,
  currentConfig: MgrepConfig
): Promise<void> {
  const current = currentConfig.ignore;
  const editing = (state.config.ignore || {}) as Partial<typeof current>;

  while (true) {
    const categories = editing.categories || {};

    const field = await p.select({
      message: "Ignore Settings - Select what to edit:",
      options: [
        {
          value: "vendor",
          label: `Ignore Vendor: ${categories.vendor ?? current.categories.vendor ? "Yes" : "No"}`,
          hint: "node_modules, vendor, Pods, etc.",
        },
        {
          value: "generated",
          label: `Ignore Generated: ${categories.generated ?? current.categories.generated ? "Yes" : "No"}`,
          hint: "dist, build, *.min.js, lock files",
        },
        {
          value: "binary",
          label: `Ignore Binary: ${categories.binary ?? current.categories.binary ? "Yes" : "No"}`,
          hint: "Images, executables, archives",
        },
        {
          value: "config",
          label: `Ignore Config: ${categories.config ?? current.categories.config ? "Yes" : "No"}`,
          hint: ".github, Dockerfile, etc.",
        },
        {
          value: "detectGenerated",
          label: `Auto-Detect Generated: ${editing.detectGenerated ?? current.detectGenerated ? "Yes" : "No"}`,
          hint: "Detect minified files, generated code",
        },
        {
          value: "additional",
          label: `Additional Patterns: ${(editing.additional || current.additional).length} patterns`,
          hint: "Add custom ignore patterns",
        },
        {
          value: "exceptions",
          label: `Exceptions: ${(editing.exceptions || current.exceptions).length} patterns`,
          hint: "Files to NOT ignore",
        },
        { value: "back", label: "<- Back", hint: "Return to main menu" },
      ],
    });

    if (p.isCancel(field) || field === "back") return;

    // Handle category toggles
    if (["vendor", "generated", "binary", "config"].includes(field)) {
      const currentVal = categories[field as keyof typeof current.categories]
        ?? current.categories[field as keyof typeof current.categories];

      const value = await p.confirm({
        message: `Ignore ${field} files?`,
        initialValue: currentVal,
      });

      if (!p.isCancel(value)) {
        if (!state.config.ignore) {
          state.config.ignore = { categories: {} } as typeof current;
        }
        if (!state.config.ignore.categories) {
          state.config.ignore.categories = {};
        }
        (state.config.ignore.categories as Record<string, boolean>)[field] = value;
        state.hasChanges = true;
      }
    }
    // Handle detectGenerated toggle
    else if (field === "detectGenerated") {
      const value = await p.confirm({
        message: "Auto-detect generated files (minified, auto-generated)?",
        initialValue: editing.detectGenerated ?? current.detectGenerated,
      });

      if (!p.isCancel(value)) {
        if (!state.config.ignore) {
          state.config.ignore = {} as typeof current;
        }
        state.config.ignore.detectGenerated = value;
        state.hasChanges = true;
      }
    }
    // Handle pattern lists
    else if (field === "additional" || field === "exceptions") {
      await editPatternList(state, field, current);
    }
  }
}
