  while (true) {
    const options = [
      { value: "add", label: "+ Add pattern", hint: "Add a new glob pattern" },
      ...patterns.map((pattern, index) => ({
        value: `remove:${index}`,
        label: `- Remove: ${pattern}`,
        hint: "Click to remove this pattern",
      })),
      { value: "back", label: "<- Back", hint: "Return to ignore settings" },
    ];

    const action = await p.select({
      message: `${label} patterns (${patterns.length} total):`,
      options,
    });

    if (p.isCancel(action) || action === "back") return;

    if (action === "add") {
      const pattern = await p.text({
        message: "Enter pattern (glob format):",
        placeholder: field === "additional" 
          ? "e.g., *.log, temp/*, .env*" 
          : "e.g., !vendor/important-lib/",
        validate: (v) => {
          if (!v || !v.trim()) {
            return "Pattern cannot be empty";
          }
          return undefined;
        },
      });

      if (!p.isCancel(pattern) && pattern) {
        patterns.push(pattern.trim());
        if (!state.config.ignore) {
          state.config.ignore = {} as typeof current;
        }
        state.config.ignore[field] = patterns;
        state.hasChanges = true;
        p.log.success(`Added pattern: ${pattern.trim()}`);
      }
    } else if (action.startsWith("remove:")) {
      const index = Number.parseInt(action.split(":")[1], 10);
      const removed = patterns.splice(index, 1)[0];
      if (!state.config.ignore) {
        state.config.ignore = {} as typeof current;
      }
      state.config.ignore[field] = patterns;
      state.hasChanges = true;
      p.log.success(`Removed pattern: ${removed}`);
    }
  }
}
