```typescript
/**
 * Save configuration to file
 */
async function saveConfig(state: TUIState): Promise<void> {
  const spinner = p.spinner();
  spinner.start("Saving configuration...");

  try {
    // Remove undefined values from config before saving
    const cleanConfig = removeUndefinedValues(state.config);

    // Write to file
    writeConfig(cleanConfig, state.target, state.cwd);

    spinner.stop("Configuration saved successfully!");

    const filePath = getConfigFilePath(state.target, state.cwd);
    p.note(`Saved to: ${filePath}`, "Success");
  } catch (error) {
    spinner.stop("Failed to save configuration");
    const message = error instanceof Error ? error.message : String(error);
    p.log.error(`Error: ${message}`);

    // Re-throw to allow caller to handle
    throw error;
  }
}

/**
 * Recursively remove undefined values from an object
 */
function removeUndefinedValues<T extends Record<string, unknown>>(obj: T): Partial<T> {
  const result: Record<string, unknown> = {};

  for (const [key, value] of Object.entries(obj)) {
    if (value === undefined) {
      continue;
    }

    if (value !== null && typeof value === "object" && !Array.isArray(value)) {
      const cleaned = removeUndefinedValues(value as Record<string, unknown>);
      if (Object.keys(cleaned).length > 0) {
        result[key] = cleaned;
      }
    } else {
      result[key] = value;
    }
  }

  return result as Partial<T>;
}
