# Task: Implement editField utility function

## Objective
Create a reusable editField utility function that handles editing different types of configuration fields with appropriate prompts and validation.

## Implementation Details

### Add to: src/lib/config-tui.ts

```typescript
/**
 * Field types for different input behaviors
 */
type FieldType =
  | "provider"
  | "text"
  | "password"
  | "number"
  | "positiveNumber"
  | "temperature"
  | "boolean"
  | "searchDepth";

/**
 * Edit a single field with appropriate prompt and validation
 */
async function editField(
  fieldType: FieldType,
  fieldName: string,
  currentValue: unknown,
  options?: {
    placeholder?: string;
    min?: number;
    max?: number;
  }
): Promise<unknown> {
  switch (fieldType) {
    case "provider": {
      const value = await p.select({
        message: `Select ${fieldName}:`,
        initialValue: currentValue as string,
        options: [
          { value: "openai", label: "OpenAI", hint: "GPT models, text-embedding-3" },
          { value: "google", label: "Google", hint: "Gemini models" },
          { value: "anthropic", label: "Anthropic", hint: "Claude models (no embeddings)" },
          { value: "ollama", label: "Ollama", hint: "Local models" },
        ],
      });
      return p.isCancel(value) ? undefined : value;
    }

    case "text": {
      const value = await p.text({
        message: `Enter ${fieldName}:`,
        initialValue: (currentValue as string) || "",
        placeholder: options?.placeholder,
      });
      return p.isCancel(value) ? undefined : value || undefined;
    }

    case "password": {
      const value = await p.password({
        message: `Enter ${fieldName}:`,
      });
      return p.isCancel(value) ? undefined : value || undefined;
    }

    case "number": {
      const value = await p.text({
        message: `Enter ${fieldName}:`,
        initialValue: currentValue?.toString() || "",
        validate: (v) => {
          if (!v) return undefined; // Allow empty to clear
          const num = Number.parseInt(v, 10);
          if (Number.isNaN(num)) {
            return "Please enter a valid number";
          }
          if (options?.min !== undefined && num < options.min) {
            return `Value must be at least ${options.min}`;
          }
          if (options?.max !== undefined && num > options.max) {
            return `Value must be at most ${options.max}`;
          }
          return undefined;
        },
      });
      if (p.isCancel(value)) return undefined;
      return value ? Number.parseInt(value, 10) : undefined;
    }

    case "positiveNumber": {
      const value = await p.text({
        message: `Enter ${fieldName}:`,
        initialValue: currentValue?.toString() || "",
        validate: (v) => {
          if (!v) return undefined;
          const num = Number.parseInt(v, 10);
          if (Number.isNaN(num) || num <= 0) {
            return "Please enter a valid positive number";
          }
          if (options?.max !== undefined && num > options.max) {
            return `Value must be at most ${options.max}`;
          }
          return undefined;
        },
      });
      if (p.isCancel(value)) return undefined;
      return value ? Number.parseInt(value, 10) : undefined;
    }

    case "temperature": {
      const value = await p.text({
        message: `Enter ${fieldName} (0-2):`,
        initialValue: currentValue?.toString() || "0.7",
        validate: (v) => {
          const num = Number.parseFloat(v);
          if (Number.isNaN(num) || num < 0 || num > 2) {
            return "Temperature must be between 0 and 2";
          }
          return undefined;
        },
      });
      if (p.isCancel(value)) return undefined;
      return Number.parseFloat(value);
    }

    case "boolean": {
      const value = await p.confirm({
        message: `Enable ${fieldName}?`,
        initialValue: currentValue as boolean,
      });
      return p.isCancel(value) ? undefined : value;
    }

    case "searchDepth": {
      const value = await p.select({
        message: `Select ${fieldName}:`,
        initialValue: currentValue as string,
        options: [
          { value: "basic", label: "Basic", hint: "Faster, less thorough" },
          { value: "advanced", label: "Advanced", hint: "Slower, more thorough" },
        ],
      });
      return p.isCancel(value) ? undefined : value;
    }

    default:
      return undefined;
  }
}

/**
 * Get display value for a field (masking sensitive data)
 */
function getDisplayValue(value: unknown, isSensitive = false): string {
  if (value === undefined || value === null || value === "") {
    return "(not set)";
  }
  if (isSensitive && typeof value === "string" && value.length > 0) {
    return "********";
  }
  return String(value);
}
```

## Supported Field Types

| Type | Prompt | Validation |
|------|--------|------------|
| provider | select | Must be valid provider |
| text | text input | None (optional) |
| password | password input | Masked |
| number | text input | Integer, min/max |
| positiveNumber | text input | Integer > 0, max |
| temperature | text input | Float 0-2 |
| boolean | confirm | true/false |
| searchDepth | select | basic/advanced |

